/** The sheet's people in list order (by position; see the move buttons), re-read whenever the sheet is loaded. */
export function usePeople(sheet: string) {
  const view = useView();
  return useQuery({
    queryKey: viewKey(peopleKey(sheet), view),
    queryFn: () => getJson<Person[]>(viewPath(`/api/sheets/${encodeURIComponent(sheet)}/people`, view)),
