    queryKey: viewKey(claimsKey(sheet), view),
    queryFn: () => getJson<Claim[]>(viewPath(`/api/sheets/${encodeURIComponent(sheet)}/claims`, view)),
    staleTime: 0,
    gcTime: 0,
  });
}

